 function showMenu(s,x,y){menu.innerHTML=[['rename',L('rename')],['auto',L('auto')],['pin',L(s.pinned?'unpin':'pin')],['archive',L(s.archived?'restore':'archive')],['copy',L('copy')],['export',L('export')]].map(([key,label])=>`<button role="menuitem" type="button" data-menu-action="${key}">${esc(label)}</button>`).join('');menu.hidden=false;menu.style.left=Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,x))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-menu.offsetHeight-8,y))+'px';menu.querySelector('button').focus();menu.onclick=async e=>{const key=e.target.closest('[data-menu-action]')?.dataset.menuAction;menu.hidden=true;if(key==='rename')rename(s);if(key==='auto')title(s);if(key==='pin'){s.pinned=!s.pinned;render()}if(key==='archive'){s.archived=!s.archived;render()}if(key==='export')downloadSession(s);if(key==='copy')try{await navigator.clipboard.writeText(s.question)}catch{input.value=s.question;input.focus()}}}
