 return {copyButton,addQuote,quotesHTML,holdReading,quoteOnly:()=>L('quoteOnly'),takeQuotes:s=>{const quotes=structuredClone(s.quoteDraft||[]);s.quoteDraft=[];return quotes},toggleNotes,imageOwner:()=>chat(),refresh,showArchived:()=>archived,label:L,nameIfUntitled:s=>{if(s.autoMetadata){if(s.autoMetadataStarted)return;s.autoMetadataStarted=true;if(!s.nameVersion)s.name=s.question.slice(0,32)||api.untitled();if(s.engine==='live')title(s,true);save();return;}if(s.name!==api.untitled())return;if(s.engine==='live')title(s);else{s.name=s.question.slice(0,32);render()}}};
